+export interface SkillDoc {
+  /** File name (e.g., "quickref.md") */
+  name: string;
+  /** Full file path */
+  path: string;
+  /** File content */
+  content: string;
+}
+
+/**
+ * Get the docs directory path for a skill.
+ * Skills can have supporting docs at .kspec/skills/<id>/docs/
