   900→/**
   901→ * Delete workflow runs by ULIDs
   902→ * AC: @workflow-prune ac-1, ac-2, ac-3, ac-4
   903→ */
   904→export async function deleteWorkflowRuns(
   905→  ctx: KspecContext,
   906→  ulidsToDelete: string[],
