      await fs.writeFile(path.join(skillDir, 'SKILL.md'), '# Test Skill');
      await fs.mkdir(path.join(skillDir, 'docs'), { recursive: true });
      await fs.writeFile(path.join(skillDir, 'docs', 'quickref.md'), '# Quick Ref');

