   172→    const dest = path.join(tempDir, entry.name);
   173→    if (entry.isDirectory()) {
   174→      await fs.cp(source, dest, { recursive: true });
   175→    } else {
   176→      await fs.copyFile(source, dest);
   177→    }
   178→  }
   179→
   180→  return tempDir;
   181→}
   182→
   183→/**
   184→ * Copy multi-directory daemon fixtures to a temp directory
   185→ *
   186→ * Creates isolated copies of multiple kspec projects for testing
   187→ * multi-directory daemon functionality.
   188→ *
   189→ * @returns Path to the temp directory containing project subdirectories
   190→ *
   191→ * @example
   192→ * const fixturesRoot = await setupMultiDirFixtures();
   193→ * const projectA = path.join(fixturesRoot, 'project-a');
   194→ * const projectB = path.join(fixturesRoot, 'project-b');
   195→ * const projectInvalid = path.join(fixturesRoot, 'project-invalid');
   196→ *
   197→ * // Clean up when done
   198→ * await cleanupTempDir(fixturesRoot);
