   200→export async function setupMultiDirFixtures(): Promise<string> {
   201→  const multiDirSource = path.join(FIXTURES_DIR, 'multi-dir');
   202→  const tempDir = await fs.mkdtemp(path.join(os.tmpdir(), 'kspec-multi-'));
