   230→ */
   231→export function initGitRepo(dir: string): void {
   232→  execSync('git init -b main', { cwd: dir, stdio: 'pipe' });
   233→  execSync('git config user.email "test@example.com"', { cwd: dir, stdio: 'pipe' });
   234→  execSync('git config user.name "Test User"', { cwd: dir, stdio: 'pipe' });
   235→}
