/**
 * Tests for Skill CLI Commands
 * AC: @skill-cli ac-1 through ac-8
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import * as fs from 'node:fs/promises';
import * as path from 'node:path';
import { parse as yamlParse, stringify as yamlStringify } from 'yaml';
import {
  kspecOutput as kspec,
  kspecJson,
  kspec as kspecFull,
  setupTempFixtures,
  cleanupTempDir,
  createTempDir,
  initGitRepo,
} from './helpers/cli';

describe('Skill CLI - skill list', () => {
  let tempDir: string;

  beforeEach(async () => {
    tempDir = await setupTempFixtures();
    await initGitRepo(tempDir);

    // Create some skills via kspec add
    kspec(
      'skill add --id task-work --name "Task Work" --description "Work on tasks" --origin core --version 0.1.0',
      tempDir
    );
