    const result = kspecJson<{ platforms: string[] }>(
      'skill add --id my-skill --name "My Skill" --platform cursor --platform windsurf',
      tempDir
    );

    expect(result.platforms).toContain('cursor');
    expect(result.platforms).toContain('windsurf');
  });

