   347→      }
   348→    });
   349→
   350→  // AC: @skill-cli ac-7, ac-8 - kspec skill delete
   351→  markMutating(skill.command("delete <ref>"))
   352→    .description("Delete a skill")
   353→    .option("--confirm", "Skip confirmation prompt")
   354→    .action(async (ref: string, options) => {
   355→      try {
   356→        const ctx = await initContext();
