   801→    return {
   802→      focus: null,
   803→      threads: [],
   804→      open_questions: [],
   805→      updated_at: new Date().toISOString(),
   806→    };
   807→  }
   808→}
   809→
   810→/**
   811→ * Save session context
   812→ */
   813→export async function saveSessionContext(
   814→  ctx: KspecContext,
   815→  context: SessionContext,
   816→): Promise<void> {
   817→  const contextPath = getSessionContextPath(ctx);
   818→
   819→  // Update timestamp
   820→  context.updated_at = new Date().toISOString();
   821→
   822→  await writeYamlFilePreserveFormat(contextPath, context);
   823→}
   824→
   825→// ============================================================
   826→// WORKFLOW RUNS
   827→// ============================================================
   828→
   829→/**
   830→ * Get the workflow runs file path.
   831→ * Derives from main manifest name (e.g., myproject.yaml -> myproject.runs.yaml)
   832→ */
   833→export function getWorkflowRunsPath(ctx: KspecContext): string {
   834→  const baseName = getManifestBaseName(ctx.manifestPath);
   835→  return path.join(ctx.specDir, `${baseName}.runs.yaml`);
   836→}
   837→
   838→/**
   839→ * Load workflow runs from file
   840→ */
   841→export async function loadWorkflowRuns(
   842→  ctx: KspecContext,
   843→): Promise<WorkflowRun[]> {
   844→  const runsPath = getWorkflowRunsPath(ctx);
   845→
   846→  try {
   847→    const raw = await readYamlFile<unknown>(runsPath);
   848→    const parsed = WorkflowRunsFileSchema.safeParse(raw);
   849→
   850→    if (!parsed.success) {
   851→      return [];
   852→    }
   853→
   854→    return parsed.data.runs;
   855→  } catch {
   856→    // File doesn't exist
   857→    return [];
   858→  }
   859→}
   860→
   861→/**
   862→ * Save a workflow run (create or update)
   863→ */
   864→export async function saveWorkflowRun(
   865→  ctx: KspecContext,
   866→  run: WorkflowRun,
   867→): Promise<void> {
   868→  const runsPath = getWorkflowRunsPath(ctx);
   869→
   870→  // Load existing runs
   871→  const runs = await loadWorkflowRuns(ctx);
   872→
   873→  // Update or add
   874→  const existingIndex = runs.findIndex((r) => r._ulid === run._ulid);
   875→  if (existingIndex >= 0) {
   876→    runs[existingIndex] = run;
   877→  } else {
   878→    runs.push(run);
   879→  }
   880→
   881→  // Save back
   882→  const runsFile: WorkflowRunsFile = {
   883→    kynetic_runs: "1.0",
   884→    runs,
   885→  };
   886→
   887→  await writeYamlFilePreserveFormat(runsPath, runsFile);
   888→}
   889→
   890→/**
   891→ * Update an existing workflow run
   892→ */
   893→export async function updateWorkflowRun(
   894→  ctx: KspecContext,
   895→  run: WorkflowRun,
   896→): Promise<void> {
   897→  await saveWorkflowRun(ctx, run);
   898→}
