   918→ * Find active workflow runs
   919→ */
   920→export async function findActiveRuns(
   921→  ctx: KspecContext,
   922→): Promise<WorkflowRun[]> {
   923→  const runs = await loadWorkflowRuns(ctx);
   924→  return runs.filter((r) => r.status === "active");
