        if (observation.resolved && !options.force) {
          error(errors.operation.cannotPromoteResolved);
          process.exit(EXIT_CODES.ERROR);
        }

        // Validate priority
        const priorityResult = parseIntOption(options.priority, {
          min: 1,
          max: 5,
          name: "Priority",
