        // Update observation with promoted_to field
        observation.promoted_to = taskRef;
        await saveObservation(ctx, observation);

        // AC: @trait-shadow-commit ac-1
        await commitIfShadow(
          ctx.shadow,
          "observation-promote",
          observation._ulid.substring(0, 8),
