            process.exit(EXIT_CODES.ERROR);
          }

          item = {
            _ulid: itemUlid,
            domain: options.domain,
            rules: options.rule || [],
            examples: [],
          };
        }

        // Save the item
        await saveMetaItem(
          ctx,
          item,
          type as "agent" | "workflow" | "convention",
        );

        // AC: @trait-shadow-commit ac-1
        await commitIfShadow(
