          success(
            `Created ${type}: ${idOrDomain} (@${itemUlid.substring(0, 8)})`,
          );
        }
      } catch (err) {
        error(errors.failures.createMeta(type), err);
        process.exit(EXIT_CODES.ERROR);
      }
    });

