   620→
   621→/**
   622→ * Save any meta item (agent, workflow, convention, skill) to the manifest
   623→ * AC: @skill-parser ac-1 - skill is appended to manifest.skills and written to disk
   624→ * AC: @skill-parser ac-2 - .kspec/skills/<id>/ directory is created for skills
   625→ */
   626→export async function saveMetaItem(
   627→  ctx: KspecContext,
   628→  item: LoadedMetaItem,
   629→  itemType: "agent" | "workflow" | "convention" | "skill",
   630→): Promise<void> {
   631→  const manifestPath = getMetaManifestPath(ctx);
   632→
   633→  // Ensure directory exists
   634→  const dir = path.dirname(manifestPath);
   635→  await fs.mkdir(dir, { recursive: true });
   636→
   637→  // Load existing manifest
   638→  let manifest: MetaManifest = {
   639→    kynetic_meta: "1.0",
   640→    agents: [],
   641→    workflows: [],
   642→    conventions: [],
   643→    observations: [],
   644→    skills: [],
   645→    includes: [],
   646→  };
   647→
   648→  try {
   649→    const raw = await readYamlFile<unknown>(manifestPath);
   650→    const parsed = MetaManifestSchema.safeParse(raw);
   651→    if (parsed.success) {
   652→      manifest = parsed.data;
   653→    }
   654→  } catch {
   655→    // File doesn't exist, use defaults
   656→  }
   657→
   658→  // Strip runtime metadata
   659→  const cleanItem = stripMetaMetadata(item);
   660→
   661→  // Get the appropriate array
   662→  const getArray = () => {
   663→    switch (itemType) {
   664→      case "agent":
   665→        return manifest.agents;
   666→      case "workflow":
   667→        return manifest.workflows;
   668→      case "convention":
   669→        return manifest.conventions;
   670→      case "skill":
   671→        return manifest.skills;
   672→    }
   673→  };
   674→
   675→  const array = getArray();
   676→
   677→  // Update or add
   678→  const existingIndex = array.findIndex((i) => i._ulid === item._ulid);
   679→  if (existingIndex >= 0) {
   680→    (array as unknown[])[existingIndex] = cleanItem;
   681→  } else {
   682→    (array as unknown[]).push(cleanItem);
   683→  }
   684→
   685→  await saveMetaManifest(manifestPath, manifest);
   686→
   687→  // AC: @skill-parser ac-2 - Create skill content directory
   688→  if (itemType === "skill" && "id" in item) {
   689→    const skillDir = path.join(ctx.specDir, "skills", item.id);
   690→    await fs.mkdir(skillDir, { recursive: true });
   691→  }
   692→}
   693→
   694→/**
   695→ * Delete any meta item from the manifest
   696→ * AC: @skill-parser ac-3 - skill is removed from manifest.skills
   697→ * AC: @skill-parser ac-4 - .kspec/skills/<id>/ directory is deleted for skills
   698→ */
   699→export async function deleteMetaItem(
   700→  ctx: KspecContext,
   701→  itemUlid: string,
   702→  itemType: "agent" | "workflow" | "convention" | "observation" | "skill",
   703→): Promise<boolean> {
   704→  const manifestPath = getMetaManifestPath(ctx);
   705→
   706→  try {
   707→    const raw = await readYamlFile<unknown>(manifestPath);
   708→    const parsed = MetaManifestSchema.safeParse(raw);
   709→    if (!parsed.success) {
   710→      return false;
   711→    }
   712→
   713→    const manifest = parsed.data;
   714→
   715→    const getArray = () => {
   716→      switch (itemType) {
   717→        case "agent":
   718→          return manifest.agents;
   719→        case "workflow":
   720→          return manifest.workflows;
   721→        case "convention":
   722→          return manifest.conventions;
   723→        case "observation":
   724→          return manifest.observations;
   725→        case "skill":
   726→          return manifest.skills;
   727→      }
   728→    };
   729→
   730→    const array = getArray();
   731→    const index = array.findIndex((i) => i._ulid === itemUlid);
   732→    if (index < 0) {
   733→      return false;
   734→    }
   735→
   736→    // AC: @skill-parser ac-4 - Delete skill directory before removing from manifest
   737→    if (itemType === "skill") {
   738→      const skill = array[index] as Skill;
   739→      if (skill.id) {
   740→        const skillDir = path.join(ctx.specDir, "skills", skill.id);
   741→        try {
   742→          await fs.rm(skillDir, { recursive: true, force: true });
   743→        } catch {
   744→          // Directory might not exist, that's fine
   745→        }
   746→      }
   747→    }
   748→
   749→    array.splice(index, 1);
   750→    await saveMetaManifest(manifestPath, manifest);
   751→    return true;
   752→  } catch {
   753→    return false;
   754→  }
   755→}
