                  id: skillId,
                  path: skillDir,
                  action: "skipped",
                  reason: "Not managed by kspec",
                });
              }
            }
          } catch {
            // No .claude/skills directory, nothing to clean
          }
        }

        // Output results
        // AC: @trait-dry-run ac-6 - JSON output includes dry_run field
        output(
          {
            dry_run: dryRun,
            rendered: results,
            cleaned: cleanResults,
          },
