   896→/**
   897→ * Parse YAML frontmatter from markdown content.
   898→ * Returns null if no valid frontmatter found.
   899→ */
   900→function parseFrontmatter(content: string): { name?: string; description?: string } | null {
   901→  const frontmatterRegex = /^---\n([\s\S]*?)\n---/;
   902→  const match = content.match(frontmatterRegex);
   903→
   904→  if (!match) {
   905→    return null;
   906→  }
   907→
   908→  try {
   909→    const parsed = yaml.parse(match[1]);
   910→
   911→    if (typeof parsed === "object" && parsed !== null) {
   912→      return {
   913→        name: typeof parsed.name === "string" ? parsed.name : undefined,
   914→        description: typeof parsed.description === "string" ? parsed.description : undefined,
   915→      };
   916→    }
   917→  } catch {
   918→    // Invalid YAML in frontmatter
   919→  }
   920→
   921→  return null;
   922→}
