   940→/**
   941→ * Recursively copy a directory
   942→ */
   943→async function copyDirectory(src: string, dest: string): Promise<void> {
   944→  const entries = await fs.readdir(src, { withFileTypes: true });
   945→
   946→  for (const entry of entries) {
   947→    const srcPath = path.join(src, entry.name);
   948→    const destPath = path.join(dest, entry.name);
   949→
   950→    if (entry.isDirectory()) {
   951→      await fs.mkdir(destPath, { recursive: true });
   952→      await copyDirectory(srcPath, destPath);
   953→    } else {
   954→      await fs.copyFile(srcPath, destPath);
   955→    }
   956→  }
   957→}
