  1017→/**
  1018→ * Recursively check if two directories have the same contents
  1019→ */
  1020→async function directoriesEqual(src: string, dest: string): Promise<boolean> {
  1021→  try {
  1022→    const srcEntries = await fs.readdir(src, { withFileTypes: true });
  1023→    const destEntries = await fs.readdir(dest, { withFileTypes: true });
  1024→
  1025→    // Different number of entries = not equal
  1026→    if (srcEntries.length !== destEntries.length) {
  1027→      return false;
  1028→    }
  1029→
  1030→    // Create a map of dest entries for quick lookup
  1031→    const destMap = new Map(destEntries.map((e) => [e.name, e]));
  1032→
  1033→    for (const srcEntry of srcEntries) {
  1034→      const destEntry = destMap.get(srcEntry.name);
  1035→      if (!destEntry) {
  1036→        return false;
  1037→      }
  1038→
  1039→      const srcPath = path.join(src, srcEntry.name);
  1040→      const destPath = path.join(dest, srcEntry.name);
  1041→
  1042→      if (srcEntry.isDirectory() && destEntry.isDirectory()) {
  1043→        if (!(await directoriesEqual(srcPath, destPath))) {
  1044→          return false;
  1045→        }
  1046→      } else if (srcEntry.isFile() && destEntry.isFile()) {
  1047→        const srcContent = await fs.readFile(srcPath, "utf-8");
  1048→        const destContent = await fs.readFile(destPath, "utf-8");
  1049→        if (!contentsEqual(srcContent, destContent)) {
  1050→          return false;
  1051→        }
  1052→      } else {
  1053→        // Type mismatch
  1054→        return false;
  1055→      }
  1056→    }
  1057→
  1058→    return true;
  1059→  } catch {
  1060→    return false;
  1061→  }
  1062→}
