   924→/**
   925→ * Normalize base-directory paths in skill content.
   926→ * AC: @skill-import ac-7 - Strip or convert absolute paths to relative.
   927→ *
   928→ * Matches patterns like:
   929→ * - "Base directory for this skill: /absolute/path/to/skill"
   930→ * - Lines starting with hardcoded paths
   931→ */
   932→function normalizeBaseDirectory(content: string): string {
   933→  // Remove or normalize "Base directory for this skill:" lines with absolute paths
   934→  // Common pattern in Claude-generated skill files
   935→  const baseDirLineRegex = /^Base directory for this skill:.*$/gm;
   936→
   937→  return content.replace(baseDirLineRegex, "");
   938→}
