   959→/**
   960→ * Marker comment that identifies skill directories managed by kspec
   961→ * AC: @skill-rendering ac-4 - Only skill directories that were rendered by kspec are considered
   962→ */
   963→const KSPEC_MANAGED_MARKER = "<!-- kspec-managed -->";
   964→
   965→/**
   966→ * Result of rendering a single skill
   967→ */
   968→interface SkillRenderResult {
   969→  id: string;
   970→  action: "created" | "updated" | "unchanged";
   971→  path: string;
   972→  docsAction?: "created" | "updated" | "unchanged" | "skipped";
   973→}
   974→
   975→/**
   976→ * Result of a clean operation
   977→ */
   978→interface CleanResult {
