   984→
   985→/**
   986→ * Generate YAML frontmatter for a skill
   987→ * AC: @skill-rendering ac-1 - .claude/skills/<id>/SKILL.md is created with YAML frontmatter
   988→ */
   989→function generateFrontmatter(skill: LoadedSkill): string {
   990→  const frontmatter: Record<string, unknown> = {
   991→    name: skill.id,
   992→    description: skill.description || skill.name,
   993→  };
   994→  return `---\n${yaml.stringify(frontmatter).trim()}\n---`;
   995→}
