  1100→      action: "created",
  1101→      path: targetSkillMd,
  1102→    };
  1103→  }
  1104→
  1105→  // Generate rendered content with frontmatter and marker
  1106→  const frontmatter = generateFrontmatter(skill);
  1107→
  1108→  // Check if source already has frontmatter - if so, strip it
