              // Print colored diff
              for (const line of diff) {
                if (line.startsWith("+") && !line.startsWith("+++")) {
                  console.log(chalk.green(line));
                } else if (line.startsWith("-") && !line.startsWith("---")) {
                  console.log(chalk.red(line));
                } else if (line.startsWith("@@")) {
                  console.log(chalk.cyan(line));
                } else {
                  console.log(line);
                }
              }
            }
          }
        );
      } catch (err) {
