        );

        let actualContent = "";
        try {
          actualContent = await fs.readFile(renderedPath, "utf-8");
        } catch {
          // File doesn't exist
        }

        // Generate diff
        const diff = generateUnifiedDiff(
          actualContent,
          expectedContent,
          `a/${skill.id}/SKILL.md`,
          `b/${skill.id}/SKILL.md`
        );

        // Output
        output(
          {
            id: skill.id,
