   620→
   621→/**
   622→ * Save any meta item (agent, workflow, convention, skill) to the manifest
   623→ * AC: @skill-parser ac-1 - skill is appended to manifest.skills and written to disk
   624→ * AC: @skill-parser ac-2 - .kspec/skills/<id>/ directory is created for skills
   625→ */
   626→export async function saveMetaItem(
   627→  ctx: KspecContext,
   628→  item: LoadedMetaItem,
   629→  itemType: "agent" | "workflow" | "convention" | "skill",
   630→): Promise<void> {
   631→  const manifestPath = getMetaManifestPath(ctx);
   632→
   633→  // Ensure directory exists
   634→  const dir = path.dirname(manifestPath);
   635→  await fs.mkdir(dir, { recursive: true });
   636→
   637→  // Load existing manifest
   638→  let manifest: MetaManifest = {
   639→    kynetic_meta: "1.0",
   640→    agents: [],
   641→    workflows: [],
   642→    conventions: [],
   643→    observations: [],
   644→    skills: [],
   645→    includes: [],
   646→  };
   647→
   648→  try {
   649→    const raw = await readYamlFile<unknown>(manifestPath);
   650→    const parsed = MetaManifestSchema.safeParse(raw);
   651→    if (parsed.success) {
   652→      manifest = parsed.data;
   653→    }
   654→  } catch {
   655→    // File doesn't exist, use defaults
   656→  }
   657→
   658→  // Strip runtime metadata
   659→  const cleanItem = stripMetaMetadata(item);
   660→
   661→  // Get the appropriate array
   662→  const getArray = () => {
   663→    switch (itemType) {
   664→      case "agent":
   665→        return manifest.agents;
   666→      case "workflow":
   667→        return manifest.workflows;
   668→      case "convention":
   669→        return manifest.conventions;
   670→      case "skill":
   671→        return manifest.skills;
   672→    }
   673→  };
   674→
   675→  const array = getArray();
   676→
   677→  // Update or add
   678→  const existingIndex = array.findIndex((i) => i._ulid === item._ulid);
   679→  if (existingIndex >= 0) {
   680→    (array as unknown[])[existingIndex] = cleanItem;
   681→  } else {
   682→    (array as unknown[]).push(cleanItem);
   683→  }
   684→
   685→  await saveMetaManifest(manifestPath, manifest);
   686→
   687→  // AC: @skill-parser ac-2 - Create skill content directory
   688→  if (itemType === "skill" && "id" in item) {
   689→    const skillDir = path.join(ctx.specDir, "skills", item.id);
   690→    await fs.mkdir(skillDir, { recursive: true });
   691→  }
   692→}
   693→
   694→/**
   695→ * Delete any meta item from the manifest
   696→ * AC: @skill-parser ac-3 - skill is removed from manifest.skills
   697→ * AC: @skill-parser ac-4 - .kspec/skills/<id>/ directory is deleted for skills
   698→ */
   699→export async function deleteMetaItem(
   700→  ctx: KspecContext,
   701→  itemUlid: string,
   702→  itemType: "agent" | "workflow" | "convention" | "observation" | "skill",
   703→): Promise<boolean> {
   704→  const manifestPath = getMetaManifestPath(ctx);
   705→
   706→  try {
   707→    const raw = await readYamlFile<unknown>(manifestPath);
   708→    const parsed = MetaManifestSchema.safeParse(raw);
   709→    if (!parsed.success) {
   710→      return false;
   711→    }
   712→
   713→    const manifest = parsed.data;
   714→
   715→    const getArray = () => {
   716→      switch (itemType) {
   717→        case "agent":
   718→          return manifest.agents;
   719→        case "workflow":
   720→          return manifest.workflows;
   721→        case "convention":
   722→          return manifest.conventions;
   723→        case "observation":
   724→          return manifest.observations;
   725→        case "skill":
   726→          return manifest.skills;
   727→      }
   728→    };
   729→
   730→    const array = getArray();
   731→    const index = array.findIndex((i) => i._ulid === itemUlid);
   732→    if (index < 0) {
   733→      return false;
   734→    }
   735→
   736→    // AC: @skill-parser ac-4 - Delete skill directory before removing from manifest
   737→    if (itemType === "skill") {
   738→      const skill = array[index] as Skill;
   739→      if (skill.id) {
   740→        const skillDir = path.join(ctx.specDir, "skills", skill.id);
   741→        try {
   742→          await fs.rm(skillDir, { recursive: true, force: true });
   743→        } catch {
   744→          // Directory might not exist, that's fine
   745→        }
   746→      }
   747→    }
   748→
   749→    array.splice(index, 1);
   750→    await saveMetaManifest(manifestPath, manifest);
   751→    return true;
   752→  } catch {
   753→    return false;
   754→  }
   755→}
   756→
   757→// ============================================================
   758→// SESSION CONTEXT
   759→// ============================================================
   760→
   761→/**
   762→ * Get the session context file path
   763→ */
   764→export function getSessionContextPath(ctx: KspecContext): string {
   765→  return path.join(ctx.specDir, ".kspec-session");
   766→}
   767→
   768→/**
   769→ * Load session context (or return empty context if not exists)
   770→ */
   771→export async function loadSessionContext(
   772→  ctx: KspecContext,
   773→): Promise<SessionContext> {
   774→  const contextPath = getSessionContextPath(ctx);
   775→
   776→  try {
   777→    const raw = await readYamlFile<unknown>(contextPath);
   778→    if (!raw || typeof raw !== "object") {
   779→      return {
   780→        focus: null,
   781→        threads: [],
   782→        open_questions: [],
   783→        updated_at: new Date().toISOString(),
   784→      };
   785→    }
   786→
   787→    // Validate and parse using schema
   788→    const result = SessionContextSchema.safeParse(raw);
   789→    if (result.success) {
   790→      return result.data;
   791→    }
   792→
   793→    // If validation fails, return empty context
   794→    return {
   795→      focus: null,
   796→      threads: [],
   797→      open_questions: [],
   798→      updated_at: new Date().toISOString(),
   799→    };
   800→  } catch {
   801→    return {
   802→      focus: null,
   803→      threads: [],
   804→      open_questions: [],
   805→      updated_at: new Date().toISOString(),
   806→    };
   807→  }
   808→}
   809→
   810→/**
   811→ * Save session context
   812→ */
   813→export async function saveSessionContext(
   814→  ctx: KspecContext,
   815→  context: SessionContext,
   816→): Promise<void> {
   817→  const contextPath = getSessionContextPath(ctx);
   818→
   819→  // Update timestamp
   820→  context.updated_at = new Date().toISOString();
   821→
   822→  await writeYamlFilePreserveFormat(contextPath, context);
   823→}
   824→
   825→// ============================================================
   826→// WORKFLOW RUNS
   827→// ============================================================
   828→
   829→/**
   830→ * Get the workflow runs file path.
   831→ * Derives from main manifest name (e.g., myproject.yaml -> myproject.runs.yaml)
   832→ */
   833→export function getWorkflowRunsPath(ctx: KspecContext): string {
   834→  const baseName = getManifestBaseName(ctx.manifestPath);
   835→  return path.join(ctx.specDir, `${baseName}.runs.yaml`);
   836→}
   837→
   838→/**
   839→ * Load workflow runs from file
   840→ */
   841→export async function loadWorkflowRuns(
   842→  ctx: KspecContext,
   843→): Promise<WorkflowRun[]> {
   844→  const runsPath = getWorkflowRunsPath(ctx);
   845→
   846→  try {
   847→    const raw = await readYamlFile<unknown>(runsPath);
   848→    const parsed = WorkflowRunsFileSchema.safeParse(raw);
   849→
   850→    if (!parsed.success) {
   851→      return [];
   852→    }
   853→
   854→    return parsed.data.runs;
   855→  } catch {
   856→    // File doesn't exist
   857→    return [];
   858→  }
   859→}
   860→
   861→/**
   862→ * Save a workflow run (create or update)
   863→ */
   864→export async function saveWorkflowRun(
   865→  ctx: KspecContext,
   866→  run: WorkflowRun,
   867→): Promise<void> {
   868→  const runsPath = getWorkflowRunsPath(ctx);
   869→
   870→  // Load existing runs
   871→  const runs = await loadWorkflowRuns(ctx);
   872→
   873→  // Update or add
   874→  const existingIndex = runs.findIndex((r) => r._ulid === run._ulid);
   875→  if (existingIndex >= 0) {
   876→    runs[existingIndex] = run;
   877→  } else {
   878→    runs.push(run);
   879→  }
   880→
   881→  // Save back
   882→  const runsFile: WorkflowRunsFile = {
   883→    kynetic_runs: "1.0",
   884→    runs,
   885→  };
   886→
   887→  await writeYamlFilePreserveFormat(runsPath, runsFile);
   888→}
   889→
   890→/**
   891→ * Update an existing workflow run
   892→ */
   893→export async function updateWorkflowRun(
   894→  ctx: KspecContext,
   895→  run: WorkflowRun,
   896→): Promise<void> {
   897→  await saveWorkflowRun(ctx, run);
   898→}
   899→
   900→/**
   901→ * Find a workflow run by reference (ULID or ULID prefix)
   902→ */
   903→export async function findWorkflowRunByRef(
   904→  ctx: KspecContext,
   905→  ref: string,
   906→): Promise<WorkflowRun | undefined> {
   907→  const runs = await loadWorkflowRuns(ctx);
   908→  const cleanRef = ref.startsWith("@") ? ref.slice(1) : ref;
   909→
   910→  return runs.find(
   911→    (r) =>
   912→      r._ulid === cleanRef ||
   913→      r._ulid.toLowerCase().startsWith(cleanRef.toLowerCase()),
   914→  );
   915→}
   916→
   917→/**
   918→ * Find active workflow runs
   919→ */
   920→export async function findActiveRuns(
   921→  ctx: KspecContext,
   922→): Promise<WorkflowRun[]> {
   923→  const runs = await loadWorkflowRuns(ctx);
   924→  return runs.filter((r) => r.status === "active");
   925→}
   926→
   927→/**
   928→ * Delete workflow runs by ULIDs
   929→ * AC: @workflow-prune ac-1, ac-2, ac-3, ac-4
   930→ */
   931→export async function deleteWorkflowRuns(
   932→  ctx: KspecContext,
   933→  ulidsToDelete: string[],
   934→): Promise<void> {
   935→  const runsPath = getWorkflowRunsPath(ctx);
   936→  const runs = await loadWorkflowRuns(ctx);
   937→
   938→  // Filter out runs to delete
   939→  const remainingRuns = runs.filter((r) => !ulidsToDelete.includes(r._ulid));
   940→
   941→  // Save back
   942→  const runsFile: WorkflowRunsFile = {
   943→    kynetic_runs: "1.0",
   944→    runs: remainingRuns,
   945→  };
   946→
   947→  await writeYamlFilePreserveFormat(runsPath, runsFile);
   948→}
