import { z } from "zod";
import { DateTimeSchema, RefSchema, UlidSchema } from "./common.js";

/**
 * ULID schema for meta items - uses the same strict validation as core items.
 * All ULIDs must be exactly 26 characters in Crockford base32 format.
 */
const MetaUlidSchema = UlidSchema;

/**
 * Agent session protocol - commands to run at session lifecycle events
 */
export const SessionProtocolSchema = z.object({
  start: z.string().nullable().optional(),
  checkpoint: z.string().nullable().optional(),
  end: z.string().nullable().optional(),
});

/**
 * Agent definition - describes an agent's role and capabilities
 */
export const AgentSchema = z.object({
  _ulid: MetaUlidSchema,
  id: z.string().min(1, "Agent ID is required"),
  name: z.string().min(1, "Agent name is required"),
  description: z.string().optional(),
  capabilities: z.array(z.string()).default([]),
  tools: z.array(z.string()).default([]),
  session_protocol: SessionProtocolSchema.optional(),
  conventions: z.array(z.string()).default([]),
});

/**
 * Workflow step types
 */
export const WorkflowStepTypeSchema = z.enum(["check", "action", "decision"]);

/**
 * Workflow step execution hints
 */
export const StepExecutionSchema = z.object({
  mode: z.enum(["prompt", "silent", "skip"]).default("prompt"),
  timeout: z.number().nullable().optional(),
});

/**
 * Workflow step input definition
 */
export const StepInputSchema = z.object({
  name: z.string().min(1, "Input name is required"),
  description: z.string().optional(),
  required: z.boolean().default(true).optional(),
  type: z.enum(["string", "ref", "number"]).default("string").optional(),
});

/**
 * Workflow step - a single step in a workflow
 */
export const WorkflowStepSchema = z.object({
  type: WorkflowStepTypeSchema,
  content: z.string(),
  on_fail: z.string().optional(),
  options: z.array(z.string()).optional(), // For decision type
  execution: StepExecutionSchema.optional(),
  entry_criteria: z.array(z.string()).optional(),
  exit_criteria: z.array(z.string()).optional(),
  inputs: z.array(StepInputSchema).optional(),
});

/**
 * Workflow mode - interactive (default) for human-in-loop, loop for autonomous agents
 */
export const WorkflowModeSchema = z.enum(["interactive", "loop"]);

/**
 * Workflow definition - structured process definition
 */
export const WorkflowSchema = z.object({
  _ulid: MetaUlidSchema,
  id: z.string().min(1, "Workflow ID is required"),
  trigger: z.string().min(1, "Workflow trigger is required"),
  description: z.string().optional(),
  steps: z.array(WorkflowStepSchema).default([]),
  enforcement: z.enum(["advisory", "strict"]).default("advisory").optional(),
  mode: WorkflowModeSchema.default("interactive").optional(),
  based_on: RefSchema.optional(),
  tags: z.array(z.string()).default([]).optional(),
});

/**
 * Convention example (good/bad)
 */
export const ConventionExampleSchema = z.object({
  good: z.string(),
  bad: z.string(),
});

/**
 * Convention validation configuration
 */
export const ConventionValidationSchema = z.object({
  type: z.enum(["regex", "enum", "range", "prose"]),
  // For regex
  pattern: z.string().optional(),
  message: z.string().optional(),
  // For enum
  allowed: z.array(z.string()).optional(),
  // For range
  min: z.number().optional(),
  max: z.number().optional(),
  unit: z.enum(["words", "chars", "lines"]).optional(),
});

/**
 * Convention definition - project-specific rules and standards
 */
export const ConventionSchema = z.object({
  _ulid: MetaUlidSchema,
  domain: z.string().min(1, "Convention domain is required"),
  rules: z.array(z.string()).default([]),
  examples: z.array(ConventionExampleSchema).default([]),
  validation: ConventionValidationSchema.optional(),
});

/**
 * Observation types
 */
export const ObservationTypeSchema = z.enum([
  "friction",
  "success",
  "question",
  "idea",
]);

/**
 * Observation - feedback about workflows and conventions
 */
export const ObservationSchema = z.object({
  _ulid: MetaUlidSchema,
  type: ObservationTypeSchema,
  workflow_ref: RefSchema.optional(),
  content: z.string().min(1, "Observation content is required"),
  created_at: DateTimeSchema,
  author: z.string().optional(),
  resolved: z.boolean().default(false),
  resolution: z.string().nullable().optional(),
  resolved_at: DateTimeSchema.optional(),
  resolved_by: z.string().optional(),
  promoted_to: RefSchema.optional(),
});

/**
 * Skill origin - where the skill comes from
 */
export const SkillOriginSchema = z.enum(["core", "project", "local"]);

/**
 * Kebab-case regex for skill IDs - lowercase letters, numbers, and hyphens only
 * Must start with a letter and not end with a hyphen
 */
const KEBAB_CASE_REGEX = /^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$/;

/**
 * Skill definition - reusable agent capabilities stored in files
 * Content is stored in .kspec/skills/<id>/SKILL.md
 */
export const SkillSchema = z.object({
  _ulid: MetaUlidSchema,
  id: z
    .string({ required_error: "Skill ID is required" })
    .regex(
      KEBAB_CASE_REGEX,
      "Skill ID must be in kebab-case format (lowercase letters, numbers, and hyphens)",
    ),
  name: z.string().min(1, "Skill name is required"),
  description: z.string().optional(),
  origin: SkillOriginSchema,
  version: z.string().optional(),
  platforms: z.array(z.string()).default(["claude-code"]),
  depends_on: z.array(RefSchema).default([]),
  tags: z.array(z.string()).default([]),
});

/**
 * Session context schema - ephemeral session state
 */
export const SessionContextSchema = z.object({
  focus: z.string().nullable(),
  threads: z.array(z.string()).default([]),
  open_questions: z.array(z.string()).default([]),
  updated_at: DateTimeSchema,
});

/**
 * Step result status
 */
export const StepResultStatusSchema = z.enum([
  "completed",
  "skipped",
  "failed",
]);

/**
 * Step result schema - result of executing a workflow step
 */
export const StepResultSchema = z.object({
  step_index: z.number(),
  status: StepResultStatusSchema,
  started_at: DateTimeSchema,
  completed_at: DateTimeSchema,
  entry_confirmed: z.boolean().optional(),
  exit_confirmed: z.boolean().optional(),
  notes: z.string().optional(),
  inputs: z.record(z.string()).optional(),
});

/**
 * Workflow run status
 */
export const WorkflowRunStatusSchema = z.enum([
  "active",
  "paused",
  "completed",
  "aborted",
]);

/**
 * Workflow run result - distinguishes between different completion types
 */
export const WorkflowRunResultSchema = z.enum([
  "success", // Normal completion through all steps
  "no_work_available", // Graceful exit - no eligible work to process
  "early_exit", // Intentional exit before all steps (not an error)
]);

/**
 * Workflow run schema - tracks execution of a workflow
 */
export const WorkflowRunSchema = z.object({
  _ulid: UlidSchema,
  workflow_ref: RefSchema,
  status: WorkflowRunStatusSchema,
  current_step: z.number(),
  total_steps: z.number(),
  started_at: DateTimeSchema,
  paused_at: DateTimeSchema.optional(),
  completed_at: DateTimeSchema.optional(),
  step_results: z.array(StepResultSchema).default([]),
  initiated_by: z.string().optional(),
  abort_reason: z.string().optional(),
  task_ref: RefSchema.optional(),
  result: WorkflowRunResultSchema.optional(), // Only set for completed runs
});

/**
 * Workflow runs file schema - container for all workflow runs
 */
export const WorkflowRunsFileSchema = z.object({
  kynetic_runs: z.string().default("1.0"),
  runs: z.array(WorkflowRunSchema).default([]),
});

/**
 * Meta manifest schema - the root structure for kynetic.meta.yaml
 */
export const MetaManifestSchema = z.object({
  kynetic_meta: z.string().default("1.0"),
  agents: z.array(AgentSchema).default([]),
  workflows: z.array(WorkflowSchema).default([]),
  conventions: z.array(ConventionSchema).default([]),
  observations: z.array(ObservationSchema).default([]),
  skills: z.array(SkillSchema).default([]),
  includes: z.array(z.string()).default([]),
});

// Type exports
export type SessionProtocol = z.infer<typeof SessionProtocolSchema>;
export type Agent = z.infer<typeof AgentSchema>;
export type WorkflowStepType = z.infer<typeof WorkflowStepTypeSchema>;
export type StepExecution = z.infer<typeof StepExecutionSchema>;
export type StepInput = z.infer<typeof StepInputSchema>;
export type WorkflowStep = z.infer<typeof WorkflowStepSchema>;
export type WorkflowMode = z.infer<typeof WorkflowModeSchema>;
export type Workflow = z.infer<typeof WorkflowSchema>;
export type ConventionExample = z.infer<typeof ConventionExampleSchema>;
export type ConventionValidation = z.infer<typeof ConventionValidationSchema>;
export type Convention = z.infer<typeof ConventionSchema>;
export type ObservationType = z.infer<typeof ObservationTypeSchema>;
export type Observation = z.infer<typeof ObservationSchema>;
export type SkillOrigin = z.infer<typeof SkillOriginSchema>;
export type Skill = z.infer<typeof SkillSchema>;
export type SessionContext = z.infer<typeof SessionContextSchema>;
export type MetaManifest = z.infer<typeof MetaManifestSchema>;
export type StepResultStatus = z.infer<typeof StepResultStatusSchema>;
export type StepResult = z.infer<typeof StepResultSchema>;
export type WorkflowRunStatus = z.infer<typeof WorkflowRunStatusSchema>;
export type WorkflowRunResult = z.infer<typeof WorkflowRunResultSchema>;
export type WorkflowRun = z.infer<typeof WorkflowRunSchema>;
export type WorkflowRunsFile = z.infer<typeof WorkflowRunsFileSchema>;

/**
 * Meta item type - union of all meta item types
 */
export type MetaItem = Agent | Workflow | Convention | Observation | Skill;

/**
 * Determine the type of a meta item
 * AC: @skill-meta-type ac-7 - skills discriminated by the origin field (unique to skills)
 */
export function getMetaItemType(
  item: MetaItem,
): "agent" | "workflow" | "convention" | "observation" | "skill" {
  if ("origin" in item) return "skill";
  if ("capabilities" in item) return "agent";
  if ("trigger" in item) return "workflow";
  if ("domain" in item) return "convention";
  return "observation";
}

import chalk from "chalk";
import { stringify as yamlStringify } from "yaml";
import type { ReferenceIndex } from "../parser/index.js";
import type { Note, Task, TaskStatus } from "../schema/index.js";
import { fieldLabels, sectionHeaders, summaries } from "../strings/labels.js";
import { formatMatchedFields, grepItem } from "../utils/grep.js";

/**
 * Check if a note has been superseded by another note.
 * A note is superseded if its ULID appears in any other note's `supersedes` field.
 */
export function isNoteSuperseded(note: Note, allNotes: Note[]): boolean {
  return allNotes.some((n) => n.supersedes === note._ulid);
}

/**
 * Filter notes to exclude superseded ones.
 * Returns only notes that have not been superseded.
 */
export function filterSupersededNotes(notes: Note[]): Note[] {
  return notes.filter((note) => !isNoteSuperseded(note, notes));
}

/**
 * Annotate notes with superseded status for JSON output.
 * Adds a computed `superseded` field to each note.
 */
export function annotateNotesWithSuperseded(
  notes: Note[],
): Array<Note & { superseded: boolean }> {
  return notes.map((note) => ({
    ...note,
    superseded: isNoteSuperseded(note, notes),
  }));
}

/**
 * Output options
 */
export interface OutputOptions {
  json?: boolean;
}

/**
 * Output format types
 * AC: @output-format-option
 */
export type OutputFormat = "text" | "json" | "yaml";

/**
 * Valid format values for --format option
 */
export const VALID_FORMATS = ["json", "yaml"] as const;

/**
 * Global output format (set by --json, --yaml, --raw, or --format flags)
 * AC: @output-format-option ac-format-json, ac-format-yaml
 */
let globalOutputFormat: OutputFormat = "text";

export function setOutputFormat(format: OutputFormat): void {
  globalOutputFormat = format;
}

export function getOutputFormat(): OutputFormat {
  return globalOutputFormat;
}

/**
 * Set JSON mode (for backward compatibility)
 * AC: @output-format-option ac-json-shorthand
 */
export function setJsonMode(enabled: boolean): void {
  if (enabled) {
    globalOutputFormat = "json";
  } else if (globalOutputFormat === "json") {
    globalOutputFormat = "text";
  }
}

/**
 * Check if JSON mode is active
 * AC: @output-format-option ac-json-shorthand
 */
export function isJsonMode(): boolean {
  return globalOutputFormat === "json";
}

/**
 * Set YAML mode
 * AC: @output-format-option ac-format-yaml, ac-yaml-shorthand
 */
export function setYamlMode(enabled: boolean): void {
  if (enabled) {
    globalOutputFormat = "yaml";
  } else if (globalOutputFormat === "yaml") {
    globalOutputFormat = "text";
  }
}

/**
 * Check if YAML mode is active
 * AC: @output-format-option ac-format-yaml
 */
export function isYamlMode(): boolean {
  return globalOutputFormat === "yaml";
}

/**
 * Check if any structured output mode is active (JSON or YAML)
 * AC: @output-format-option ac-yaml-no-ansi, ac-yaml-references
 */
export function isStructuredMode(): boolean {
  return globalOutputFormat === "json" || globalOutputFormat === "yaml";
}

/**
 * Global verbose mode (set by --verbose flag)
 */
let globalVerboseMode = false;

export function setVerboseMode(enabled: boolean): void {
  globalVerboseMode = enabled;
}

export function getVerboseMode(): boolean {
  return globalVerboseMode;
}

/**
 * Output data - JSON/YAML if structured mode, otherwise formatted
 * AC: @output-format-option ac-format-json, ac-format-yaml
 */
export function output(data: unknown, formatter?: () => void): void {
  if (globalOutputFormat === "json") {
    console.log(JSON.stringify(data, null, 2));
  } else if (globalOutputFormat === "yaml") {
    console.log(yamlStringify(data, { indent: 2 }));
  } else if (formatter) {
    formatter();
  } else {
    console.log(data);
  }
}

/**
 * Output success message
 * AC: @output-format-option ac-format-json, ac-format-yaml
 */
export function success(message: string, data?: Record<string, unknown>): void {
  if (globalOutputFormat === "json") {
    console.log(JSON.stringify({ success: true, message, ...data }));
  } else if (globalOutputFormat === "yaml") {
    console.log(yamlStringify({ success: true, message, ...data }, { indent: 2 }));
  } else {
    console.log(chalk.green("OK"), message);
  }
}

/**
 * Output error message
 * AC: @output-format-option ac-format-json, ac-format-yaml
 */
export function error(message: string, details?: unknown): void {
  if (globalOutputFormat === "json") {
    console.error(JSON.stringify({ success: false, error: message, details }));
  } else if (globalOutputFormat === "yaml") {
    console.error(yamlStringify({ success: false, error: message, details }, { indent: 2 }));
  } else {
    console.error(chalk.red("✗"), message);
    if (details) {
      console.error(chalk.gray(String(details)));
      // Show suggestion if it's a ShadowError with a suggestion
      if (details && typeof details === "object" && "suggestion" in details) {
        const suggestion = (details as { suggestion?: string }).suggestion;
        if (suggestion) {
          console.error(chalk.yellow("  Suggestion:"), suggestion);
        }
      }
    }
  }
}

/**
 * Output warning message
 * AC: @output-format-option ac-yaml-no-ansi
 */
export function warn(message: string): void {
  if (isStructuredMode()) {
    // Warnings are suppressed in structured output modes
  } else {
    console.warn(chalk.yellow("⚠"), message);
  }
}

/**
 * Output info message
 * AC: @output-format-option ac-yaml-no-ansi
 */
export function info(message: string): void {
  if (isStructuredMode()) {
    // Info messages suppressed in structured output modes
  } else {
    console.log(chalk.blue("ℹ"), message);
  }
}

/**
 * Get color for task status
 */
function statusColor(status: TaskStatus): (text: string) => string {
  switch (status) {
    case "pending":
      return (t: string) => chalk.gray(t);
    case "in_progress":
      return (t: string) => chalk.blue(t);
    case "blocked":
      return (t: string) => chalk.red(t);
    case "completed":
      return (t: string) => chalk.green(t);
    case "cancelled":
      return (t: string) => chalk.strikethrough.gray(t);
    default:
      return (t: string) => chalk.white(t);
  }
}

/**
 * Format a task reference (short ULID + slug if available)
 * @param task The task to format
 * @param index Optional ReferenceIndex for dynamic short ULID computation
 */
export function formatTaskRef(task: Task, index?: ReferenceIndex): string {
  const shortId = index ? index.shortUlid(task._ulid) : task._ulid.slice(0, 8);
  if (task.slugs.length > 0) {
    return `${shortId} (${task.slugs[0]})`;
  }
  return shortId;
}

/**
 * Format task for display
 */
export function formatTask(
  task: Task,
  verbose = false,
  index?: ReferenceIndex,
  full = false,
): string {
  const ref = formatTaskRef(task, index);
  const status = statusColor(task.status)(`[${task.status}]`);
  const priority =
    task.priority <= 2
      ? chalk.red(`P${task.priority}`)
      : chalk.gray(`P${task.priority}`);

  let line = `${ref} ${status} ${priority} ${task.title}`;

  if (verbose && !full) {
    // AC: @task-list-verbose ac-2 - Single verbose (-v) shows current behavior
    if (task.spec_ref) {
      line += chalk.gray(` (spec: ${task.spec_ref})`);
    }
    if (task.depends_on.length > 0) {
      line += chalk.gray(` deps: [${task.depends_on.join(", ")}]`);
    }
    if (task.tags.length > 0) {
      line += chalk.cyan(` #${task.tags.join(" #")}`);
    }
  }

  return line;
}

/**
 * Get first line of text, truncated to max length
 */
function getFirstLine(
  text: string | undefined,
  maxLength: number = 70,
): string | undefined {
  if (!text) return undefined;
  const firstLine = text.split("\n")[0].trim();
  if (firstLine.length <= maxLength) return firstLine;
  return `${firstLine.slice(0, maxLength - 3)}...`;
}

/**
 * Format full mode context for a task (AC-1, AC-3, AC-5)
 */
function formatFullModeContext(task: Task, index?: ReferenceIndex): void {
  const indent = "    ";

  // Show timestamps (AC-1)
  console.log(chalk.gray(`${indent}Created: ${task.created_at}`));
  if (task.started_at) {
    console.log(chalk.gray(`${indent}Started: ${task.started_at}`));
  }
  if (task.completed_at) {
    console.log(chalk.gray(`${indent}Completed: ${task.completed_at}`));
  }

  // Show notes count and most recent note (AC-1, AC-3)
  if (task.notes && task.notes.length > 0) {
    const mostRecent = task.notes[task.notes.length - 1];
    const preview = getFirstLine(mostRecent.content, 50);
    console.log(
      chalk.gray(`${indent}Notes: ${task.notes.length} (latest: "${preview}")`),
    );
  }

  // Show pending todos count (AC-1, AC-3)
  if (task.todos && task.todos.length > 0) {
    const pendingCount = task.todos.filter((t) => !t.done).length;
    if (pendingCount > 0) {
      console.log(chalk.gray(`${indent}Pending todos: ${pendingCount}`));
    }
  }

  // Show spec context (AC-5)
  if (task.spec_ref && index) {
    const result = index.resolve(task.spec_ref);
    if (result.ok) {
      const spec = result.item;
      const specName =
        "title" in spec
          ? spec.title
          : "name" in spec
            ? spec.name
            : "id" in spec
              ? spec.id
              : task.spec_ref;
      console.log(chalk.gray(`${indent}Spec: ${task.spec_ref}`));
      console.log(chalk.cyan(`${indent}  ${specName}`));

      // Show spec description if available
      if ("description" in spec && spec.description) {
        const descPreview = getFirstLine(spec.description as string, 70);
        console.log(chalk.gray(`${indent}  ${descPreview}`));
      }

      // Show acceptance criteria if available
      if (
        "acceptance_criteria" in spec &&
        Array.isArray(spec.acceptance_criteria)
      ) {
        const ac = spec.acceptance_criteria;
        if (ac.length > 0) {
          console.log(
            chalk.gray(`${indent}  Acceptance Criteria: ${ac.length}`),
          );
          // Show first AC as preview
          const firstAC = ac[0];
          if (
            typeof firstAC === "object" &&
            firstAC !== null &&
            "id" in firstAC
          ) {
            console.log(
              chalk.gray(`${indent}    [${firstAC.id}] ${firstAC.then}`),
            );
          }
        }
      }
    }
  }

  // Show tags and dependencies if present
  if (task.tags && task.tags.length > 0) {
    console.log(chalk.gray(`${indent}Tags: ${task.tags.join(", ")}`));
  }
  if (task.depends_on && task.depends_on.length > 0) {
    console.log(
      chalk.gray(`${indent}Depends on: ${task.depends_on.join(", ")}`),
    );
  }
}

/**
 * Format automation status as a colored label
 * AC: @task-automation-eligibility ac-14
 */
function formatAutomationStatus(automation: string | undefined): string {
  if (!automation) {
    return chalk.gray("[unassessed]");
  }
  switch (automation) {
    case "eligible":
      return chalk.green("[eligible]");
    case "needs_review":
      return chalk.yellow("[needs_review]");
    case "manual_only":
      return chalk.red("[manual_only]");
    default:
      return chalk.gray(`[${automation}]`);
  }
}

/**
 * Format a list of tasks with automation status
 * AC: @task-automation-eligibility ac-14
 */
export function formatTaskListWithAutomation(
  tasks: Task[],
  verbose = false,
  index?: ReferenceIndex,
  grepPattern?: string,
  full = false,
): void {
  if (tasks.length === 0) {
    console.log(summaries.noTasks);
    return;
  }

  for (const task of tasks) {
    const ref = formatTaskRef(task, index);
    const status = statusColor(task.status)(`[${task.status}]`);
    const priority =
      task.priority <= 2
        ? chalk.red(`P${task.priority}`)
        : chalk.gray(`P${task.priority}`);
    const automationLabel = formatAutomationStatus(task.automation);

    let line = `${ref} ${status} ${priority} ${automationLabel} ${task.title}`;

    if (verbose && !full) {
      if (task.spec_ref) {
        line += chalk.gray(` (spec: ${task.spec_ref})`);
      }
      if (task.depends_on.length > 0) {
        line += chalk.gray(` deps: [${task.depends_on.join(", ")}]`);
      }
      if (task.tags.length > 0) {
        line += chalk.cyan(` #${task.tags.join(" #")}`);
      }
    }

    console.log(line);

    // Show matched fields if grep pattern provided
    if (grepPattern) {
      const match = grepItem(
        task as unknown as Record<string, unknown>,
        grepPattern,
      );
      if (match && match.matchedFields.length > 0) {
        console.log(
          chalk.gray(
            `    matched: ${formatMatchedFields(match.matchedFields)}`,
          ),
        );
      }
    } else if (full) {
      formatFullModeContext(task, index);
    } else {
      // Show context line: first line of description (if present)
      const context = getFirstLine(task.description);
      if (context) {
        console.log(chalk.gray(`    ${context}`));
      }
    }
  }

  console.log(summaries.taskCount(tasks.length));
}

/**
 * Format a list of tasks
 */
export function formatTaskList(
  tasks: Task[],
  verbose = false,
  index?: ReferenceIndex,
  grepPattern?: string,
  full = false,
): void {
  if (tasks.length === 0) {
    console.log(summaries.noTasks);
    return;
  }

  for (const task of tasks) {
    console.log(formatTask(task, verbose, index, full));

    // Show matched fields if grep pattern provided
    if (grepPattern) {
      const match = grepItem(
        task as unknown as Record<string, unknown>,
        grepPattern,
      );
      if (match && match.matchedFields.length > 0) {
        console.log(
          chalk.gray(
            `    matched: ${formatMatchedFields(match.matchedFields)}`,
          ),
        );
      }
    } else if (full) {
      // AC: @task-list-verbose ac-1 - Full mode shows richer context
      formatFullModeContext(task, index);
    } else {
      // Show context line: first line of description (if present)
      const context = getFirstLine(task.description);
      if (context) {
        console.log(chalk.gray(`    ${context}`));
      }
    }
  }

  console.log(summaries.taskCount(tasks.length));
}

export interface FormatTaskDetailsOptions {
  /** Show all notes including superseded ones (default: false) */
  showAllNotes?: boolean;
}

/**
 * Format task details
 */
export function formatTaskDetails(
  task: Task,
  index?: ReferenceIndex,
  options: FormatTaskDetailsOptions = {},
): void {
  console.log(chalk.bold(task.title));
  console.log(chalk.gray("─".repeat(40)));
  console.log(`${fieldLabels.ulid}      ${task._ulid}`);
  if (task.slugs.length > 0) {
    console.log(`${fieldLabels.slugs}     ${task.slugs.join(", ")}`);
  }
  console.log(`${fieldLabels.type}      ${task.type}`);
  console.log(
    `${fieldLabels.status}    ${statusColor(task.status)(task.status)}`,
  );
  console.log(`${fieldLabels.priority}  ${task.priority}`);

  // AC: @task-automation-eligibility ac-17 - show automation status
  const automationDisplay = task.automation || "unassessed";
  const automationColor =
    task.automation === "eligible"
      ? chalk.green
      : task.automation === "needs_review"
        ? chalk.yellow
        : task.automation === "manual_only"
          ? chalk.red
          : chalk.gray;
  console.log(
    `${fieldLabels.automation} ${automationColor(automationDisplay)}`,
  );

  if (task.spec_ref) {
    console.log(`${fieldLabels.specRef}  ${task.spec_ref}`);
  }

  // AC: @plan-derive ac-6 - display plan_ref
  if (task.plan_ref) {
    console.log(`Plan ref:  ${task.plan_ref}`);
  }

  if (task.depends_on.length > 0) {
    if (index) {
      console.log(fieldLabels.depends);
      for (const ref of task.depends_on) {
        const result = index.resolve(ref);
        if (result.ok) {
          const item = result.item;
          const status =
            "status" in item && typeof item.status === "string"
              ? statusColor(item.status as TaskStatus)(`[${item.status}]`)
              : chalk.gray("[spec]");
          // Handle both spec items (with title) and meta items (with name or id)
          const itemName =
            "title" in item
              ? item.title
              : "name" in item
                ? item.name
                : "id" in item
                  ? item.id
                  : ref;
          console.log(`  ${ref} ${chalk.gray("→")} ${itemName} ${status}`);
        } else {
          console.log(`  ${ref} ${chalk.red("(unresolved)")}`);
        }
      }
    } else {
      console.log(`${fieldLabels.depends}   ${task.depends_on.join(", ")}`);
    }
  }

  if (task.blocked_by.length > 0) {
    console.log(
      chalk.red(`${fieldLabels.blocked}   ${task.blocked_by.join(", ")}`),
    );
  }

  if (task.tags.length > 0) {
    console.log(`${fieldLabels.tags}      ${task.tags.join(", ")}`);
  }

  console.log(`${fieldLabels.created}   ${task.created_at}`);
  if (task.started_at) {
    console.log(`${fieldLabels.started}   ${task.started_at}`);
  }
  if (task.completed_at) {
    console.log(`${fieldLabels.completed} ${task.completed_at}`);
  }

  // Show resolved spec information
  if (task.spec_ref && index) {
    const result = index.resolve(task.spec_ref);
    if (result.ok) {
      const spec = result.item;
      console.log(`\n${sectionHeaders.specContext}`);
      // Handle both spec items (with title) and meta items (with name)
      const specName =
        "title" in spec
          ? spec.title
          : "name" in spec
            ? spec.name
            : "id" in spec
              ? spec.id
              : task.spec_ref;
      console.log(chalk.cyan(specName));
      if ("type" in spec && spec.type) {
        console.log(chalk.gray(`${fieldLabels.type} ${spec.type}`));
      }
      // Show implementation status
      if ("status" in spec && spec.status && typeof spec.status === "object") {
        const status = spec.status as {
          maturity?: string;
          implementation?: string;
        };
        if (status.implementation) {
          const implColor =
            status.implementation === "verified"
              ? chalk.green
              : status.implementation === "implemented"
                ? chalk.cyan
                : status.implementation === "in_progress"
                  ? chalk.yellow
                  : chalk.gray;
          console.log(
            chalk.gray(fieldLabels.implementation) +
              implColor(status.implementation),
          );
        }
      }
      if ("description" in spec && spec.description) {
        console.log(chalk.gray(fieldLabels.description));
        // Indent description lines
        const desc = String(spec.description).trim();
        for (const line of desc.split("\n")) {
          console.log(chalk.gray(`  ${line}`));
        }
      }
      if (
        "acceptance_criteria" in spec &&
        Array.isArray(spec.acceptance_criteria) &&
        spec.acceptance_criteria.length > 0
      ) {
        console.log(chalk.gray(fieldLabels.acceptanceCriteria));
        for (const ac of spec.acceptance_criteria) {
          if (ac && typeof ac === "object" && "id" in ac) {
            const acObj = ac as {
              id: string;
              given?: string;
              when?: string;
              then?: string;
            };
            console.log(chalk.gray(`  [${acObj.id}]`));
            if (acObj.given)
              console.log(chalk.gray(`    Given: ${acObj.given}`));
            if (acObj.when) console.log(chalk.gray(`    When: ${acObj.when}`));
            if (acObj.then) console.log(chalk.gray(`    Then: ${acObj.then}`));
          }
        }
      }
      // Show traceability if present
      if (
        "traceability" in spec &&
        spec.traceability &&
        typeof spec.traceability === "object"
      ) {
        const trace = spec.traceability as {
          implementation?: Array<{
            path: string;
            function?: string;
            lines?: string;
          }>;
          tests?: Array<{ path: string }>;
          commits?: string[];
          issues?: string[];
        };
        const hasTrace =
          trace.implementation?.length ||
          trace.tests?.length ||
          trace.commits?.length ||
          trace.issues?.length;
        if (hasTrace) {
          console.log(chalk.gray(fieldLabels.traceability));
          if (trace.implementation?.length) {
            for (const impl of trace.implementation) {
              let loc = `  Code: ${impl.path}`;
              if (impl.function) loc += `::${impl.function}`;
              if (impl.lines) loc += `:${impl.lines}`;
              console.log(chalk.gray(loc));
            }
          }
          if (trace.tests?.length) {
            for (const test of trace.tests) {
              console.log(chalk.gray(`  Test: ${test.path}`));
            }
          }
          if (trace.commits?.length) {
            console.log(chalk.gray(`  Commits: ${trace.commits.join(", ")}`));
          }
          if (trace.issues?.length) {
            console.log(chalk.gray(`  Issues: ${trace.issues.join(", ")}`));
          }
        }
      }
    }
  }

  if (task.notes.length > 0) {
    // Filter superseded notes unless showAllNotes is true
    const notesToShow = options.showAllNotes
      ? task.notes
      : filterSupersededNotes(task.notes);
    const hiddenCount = task.notes.length - notesToShow.length;

    console.log(`\n${sectionHeaders.notes}`);
    for (const note of notesToShow) {
      const author = note.author || "unknown";
      // Mark if this note supersedes another
      const supersededLabel = note.supersedes ? chalk.gray(" (supersedes earlier note)") : "";
      console.log(chalk.gray(`[${note.created_at}] ${author}:`) + supersededLabel);
      console.log(note.content);
    }

    // Show count of hidden notes if any
    if (hiddenCount > 0) {
      console.log(chalk.gray(`\n(${hiddenCount} superseded note${hiddenCount > 1 ? "s" : ""} hidden - use --all to show)`));
    }
  }

  if (task.todos.length > 0) {
    console.log(`\n${sectionHeaders.todos}`);
    for (const todo of task.todos) {
      const check = todo.done ? chalk.green("✓") : chalk.gray("○");
      const text = todo.done ? chalk.strikethrough.gray(todo.text) : todo.text;
      console.log(`${check} [${todo.id}] ${text}`);
    }
  }
}

