      stdio: 'ignore',
      cwd: process.cwd(),
      env: { ...process.env, BUN_ENV: 'production' },
    });

    // Detach from parent
    child.unref();

    // Don't wait for daemon to start - let it happen in background
  } catch {
    // Errors during auto-start are non-fatal - continue with command
  }
}

